{"code":"import urllib.request
import urllib.parse
import json

# Search Wikipedia for French people in the American Civil War
query = "French people American Civil War"
url = f"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={urllib.parse.quote(query)}&format=json"

try:
    with urllib.request.urlopen(url) as response:
        data = json.loads(response.read().decode())
        if 'query' in data and 'search' in data['query']:
            for hit in data['query']['search'][:3]:
                print(f"Title: {hit['title']}")
                print(f"Snippet: {hit['snippet'][:200]}...")
                print("---")
        else:
            print("No results found")
except Exception as e:
    print(f"Error: {e}")
